<?php
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
require_once '../config/database.php';
require_once '../config/customer_order_access.php';
$userId = (string)($_SESSION['customer_user_id'] ?? '');
if ($userId === '') { header('Location: scan_qr.php'); exit; }
require_customer_order_access($userId);
$customerStmt = $conn->prepare('SELECT user_id, full_name, status, loyalty_points FROM users WHERE user_id=? LIMIT 1');
$customerStmt->bind_param('s', $userId); $customerStmt->execute(); $customer = $customerStmt->get_result()->fetch_assoc();
if (!$customer || strtolower((string)($customer['status'] ?? '')) !== 'approved') { header('Location: scan_qr.php'); exit; }
$activeStmt = $conn->prepare("SELECT transaction_id, quantity, container_size, delivery_status, status FROM transactions WHERE user_id=? AND transaction_id NOT LIKE 'RWD-%' AND (status='pending' OR (status='approved' AND LOWER(COALESCE(delivery_status,'pending')) <> 'delivered')) ORDER BY created_at DESC LIMIT 1");
$activeStmt->bind_param('s', $userId); $activeStmt->execute(); $active = $activeStmt->get_result()->fetch_assoc();
$lastStmt = $conn->prepare("SELECT quantity, container_size, container_status, fulfillment_method FROM transactions WHERE user_id=? AND transaction_id NOT LIKE 'RWD-%' AND (LOWER(COALESCE(delivery_status,''))='delivered' OR status='completed') ORDER BY created_at DESC LIMIT 1");
$lastStmt->bind_param('s', $userId); $lastStmt->execute(); $last = $lastStmt->get_result()->fetch_assoc();
$sizeNames=['5gal-round'=>'19L Round','5gal-slim'=>'19L Slim','2.5gal-slim'=>'9.5L Slim'];
$firstName=explode(' ',trim((string)$customer['full_name']))[0] ?: 'Customer';
$purchase='purchase.php?user_id='.urlencode($userId);
$reorder=$purchase;
if ($last) $reorder.='&'.http_build_query(['container_size'=>$last['container_size'],'container'=>$last['container_status'],'quantity'=>max(1,(int)$last['quantity']),'fulfillment'=>$last['fulfillment_method']]);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Dashboard | HydroMIS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Sora:wght@600;700;800&display=swap" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><style>
