order-radius:13px;background:#fff2d4;color:#b6740c}.rewards h2{margin:13px 0 5px;font-size:17px}.rewards strong{font:800 30px Sora;color:#1676a6}.rewards p{color:var(--muted);font-size:13px}.rewards a{color:#147fc7;text-decoration:none;font-size:13px;font-weight:800}.section{margin:33px 0 15px;font-size:18px}.actions{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.action{display:block;padding:19px;color:var(--ink);text-decoration:none;transition:.2s}.action:hover{border-color:#50c2df;transform:translateY(-3px);box-shadow:0 13px 25px rgba(15,89,121,.09)}.action i{display:grid;place-items:center;width:40px;height:40px;margin-bottom:14px;border-radius:12px;background:#e8f7fc;color:#1682bd}.action h3{font-size:15px}.action p{margin:7px 0 0;color:var(--muted);font-size:12px;line-height:1.5}.action span{display:inline-block;margin-top:14px;color:#147fc7;font-size:12px;font-weight:800}.secondary{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.small{padding:15px;color:#31546b;text-decoration:none;font-size:13px;font-weight:700}.small i{margin-right:8px;color:#1682bd}@media(max-width:760px){.intro,.top-grid{display:block}.intro p{margin-top:12px}.rewards{margin-top:15px}.actions,.secondary{grid-template-columns:1fr}.page{padding-top:30px}}
</style></head><body><nav class="nav"><a class="brand" href="dashboard.php"><img src="../imagess/hydromis-logo-v2.png" alt="HydroMIS">Hydro<span>MIS</span></a><a class="logout" href="../logout.php">Log out</a></nav><main class="page"><div class="intro"><div><span class="eyebrow">Customer dashboard</span><h1>Good day, <?php echo htmlspecialchars($firstName); ?>.</h1></div><p>Manage orders, delivery status, rewards, and your next water request from one place.</p></div><div class="top-grid"><section class="active"><span class="label"><i class="fa-solid fa-truck"></i> <?php echo $active ? 'Active order' : 'Ready when you are'; ?></span><?php if($active): ?><h2>Your order is being processed</h2><p>View the latest delivery update and track your rider.</p><div class="pills"><span class="pill"><?php echo (int)$active['quantity']; ?> × <?php echo htmlspecialchars($sizeNames[$active['container_size']] ?? 'Water gallon'); ?></span><span class="pill"><?php echo htmlspecialchars(ucfirst((string)($active['delivery_status'] ?: $active['status']))); ?></span></div><a class="primary" href="track_order.php?user_id=<?php echo urlencode($userId); ?>">Track active order <i class="fa-solid fa-arrow-right"></i></a><?php else: ?><h2>No active order right now</h2><p>Choose a water order below to begin the secure checkout process.</p><a class="primary" href="<?php echo htmlspecialchars($purchase); ?>">Start a new order <i class="fa-solid fa-arrow-right"></i></a><?php endif; ?></section><aside class="rewards"><i class="fa-solid fa-gift"></i><h2>Hydro Rewards</h2><strong><?php echo (int)($customer['loyalty_points'] ?? 0); ?> pts</strong><p>Earn and redeem points on eligible orders.</p><a href="rewards.php?user_id=<?php echo urlencode($userId); ?>">View rewards <i class="fa-solid fa-arrow-right"></i></a></aside></div><h2 class="section">Start or continue an order</h2><section class="actions"><a class="action" href="<?php echo htmlspecialchars($reorder); ?>"><i class="fa-solid fa-rotate-right"></i><h3>Order again</h3><p><?php echo $last ? 'Reuse your last delivered order and adjust it if needed.' : 'Start a new water request.'; ?></p><span>Build order <i class="fa-solid fa-arrow-right"></i></span></a><a class="action" href="<?php echo htmlspecialchars($purchase); ?>&amp;container=existing"><i class="fa-solid fa-recycle"></i><h3>New refill</h3><p>Build a refill order for your existing gallon container.</p><span>Build refill <i class="fa-solid fa-arrow-right"></i></span></a><a class="action" href="<?php echo htmlspecialchars($purchase); ?>&amp;container=new"><i class="fa-solid fa-bottle-water"></i><h3>New gallon order</h3><p>Build an order that includes a new water container.</p><span>Build order <i class="fa-solid fa-arrow-right"></i></span></a></section><section class="secondary"><a class="small" href="track_order.php?user_id=<?php echo urlencode($userId); ?>"><i class="fa-solid fa-clock-rotate-left"></i>Order history and tracking</a><a class="small" href="scan_qr.php"><i class="fa-solid fa-qrcode"></i>Account and QR access</a></section></main></body></html>
